llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Lycopene, a long-chain isoprenoid with extreme lipophilicity, showed only 0.17% systemic availability after ingestion in tomato paste, supporting low oral bioavailability for the similarly large and lipophilic CoQ10 query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lycopene in capsules gave approximately 2.6% bioavailability, reinforcing that highly lipophilic isoprenoid molecules generally have poor systemic availability unless specially formulated.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "A 13C-labeled lycopene study reported 24.5% bioavailability for cis-lycopene, showing that some isoprenoid formulations can exceed 20%, but this is formulation/isomer-dependent and does not overcome the query's larger size and poorer solubility.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Etretinate, a highly lipophilic retinoid with very low aqueous solubility, achieved about 40% absolute bioavailability, indicating that lipophilicity alone does not preclude F≥20%; however, its much lower molecular weight limits transferability to the 863 Da CoQ10 query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, an extremely lipophilic 863 Da benzoquinone with a long isoprenoid tail. The most relevant analogues are long-chain isoprenoids: lycopene generally shows low systemic availability (<3%) in food/capsule studies, while a labeled lycopene study reached ~24% and retinoids ~40-60%. The query's higher molecular weight, extreme logP, lack of ionizable groups, and expected poor dissolution favor F<20%. Small-molecule high-bioavailability records are not transferable to this physicochemical extreme.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ10/ubiquinone are present in the evidence set.",
    "Lycopene bioavailability values are strongly confounded by formulation, food matrix, and isomer composition.",
    "No IV comparator data exist for the query molecule itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

